#!/usr/bin/env python
"""
Script to reproduce the aslist issue with non-string objects.
"""

def test_aslist_issue():
    """Test the reported issue with aslist and non-string objects."""
    from src.pyramid.settings import aslist

    print("Testing aslist with various inputs...")

    # This should work fine
    try:
        result = aslist(['abc', 'def'])
        print(f"✓ aslist(['abc', 'def']) = {result}")
    except Exception as e:
        print(f"✗ aslist(['abc', 'def']) failed: {e}")

    # This should raise AttributeError according to the issue
    try:
        result = aslist([1])
        print(f"✓ aslist([1]) = {result}")
    except Exception as e:
        print(f"✗ aslist([1]) failed: {e}")

    # This should also raise the same error
    try:
        result = aslist([' abc def ghi ', 1])
        print(f"✓ aslist([' abc def ghi ', 1]) = {result}")
    except Exception as e:
        print(f"✗ aslist([' abc def ghi ', 1]) failed: {e}")

    # Additional test cases
    try:
        result = aslist([1, 2, 3])
        print(f"✓ aslist([1, 2, 3]) = {result}")
    except Exception as e:
        print(f"✗ aslist([1, 2, 3]) failed: {e}")

    # Test with mixed types
    try:
        result = aslist(['hello world', 42, 'foo bar', None])
        print(f"✓ aslist(['hello world', 42, 'foo bar', None]) = {result}")
    except Exception as e:
        print(f"✗ aslist(['hello world', 42, 'foo bar', None]) failed: {e}")

    # Test with flatten=False - should work fine
    try:
        result = aslist([1], flatten=False)
        print(f"✓ aslist([1], flatten=False) = {result}")
    except Exception as e:
        print(f"✗ aslist([1], flatten=False) failed: {e}")

if __name__ == "__main__":
    test_aslist_issue()

